#!/usr/bin/env python3
"""
compute_j5.py -- TASK-20261002-8d288b, blind re-derivation of joint J5.

Computes the card's quantities Q1..Q4 from the verbatim output of
    openssl ecparam -name <row> -param_enc explicit -text -noout
and nothing else.  Usage:
    python3 compute_j5.py <raw_dir> <out_json>

impl-1 (primary, every reported value comes from here):
    own GF(2)[t]/(f) arithmetic on Python ints (bit j = coefficient of t^j),
    own Frobenius iteration, own xor-basis rank over GF(2), own extended
    Euclid inversion, own Rabin irreducibility test, sympy.isprime
    (strong Baillie-PSW for these sizes), mpmath for Q3/Q4.
impl-2 (cross-check; shares no field-arithmetic or rank code with impl-1):
    squaring map as an N x N matrix over GF(2) whose columns t^(2j) mod f are
    produced by sympy.polys.galoistools.gf_rem and applied with numpy;
    ranks by sympy DomainMatrix over GF(2); absolute trace by Newton's
    identities on the coefficients of f; degree over F_2 by the rank of the
    power matrix {1, x, ..., x^(N-1)} built with sympy gf_mul/gf_rem;
    Ord_sigma(b) by sympy factorisation of x^n - 1 over GF(2); Lucas values
    by x^k mod (x^2 - t x + q0) over Z; own Miller-Rabin with seeded random
    bases; Q3 by the decimal module with an own Machin pi; Q4 by exact
    fractions; curve-equation check with sympy gf_mul/gf_rem.
"""
import json
import math
import os
import platform
import random
import re
import resource
import sys
import time
from decimal import Decimal, localcontext, ROUND_HALF_EVEN, ROUND_HALF_UP
from fractions import Fraction

import mpmath
import numpy as np
import sympy
from sympy import GF as SymGF
from sympy import Poly, symbols
from sympy.polys import galoistools as gt
from sympy.polys.domains import ZZ
from sympy.polys.matrices import DomainMatrix

RAW_DIR, OUT = sys.argv[1], sys.argv[2]
ROWS_COMPOSITE = ["c2pnb176v1", "c2pnb208w1", "c2pnb272w1", "c2pnb304w1", "c2pnb368w1"]
ROWS_CONTROL = ["c2tnb191v1", "c2tnb239v1"]
ROWS = ROWS_COMPOSITE + ROWS_CONTROL
if len(sys.argv) > 3:                      # optional smoke-test subset; the reported run uses all rows
    ROWS = [r for r in ROWS if r in sys.argv[3].split(",")]
SEED = 0x8D288B
RNG = random.Random(SEED)
TIMINGS = {}
T_START = time.perf_counter()


def tick(name, t0):
    TIMINGS[name] = round(TIMINGS.get(name, 0.0) + (time.perf_counter() - t0), 3)


# =========================================================== parsing (P1, P2)
HEX_LINE = re.compile(r"^[0-9a-f]{2}(:[0-9a-f]{2})*:?$")


def parse_p1(text):
    """Line-state parser: header lines begin in column 0 and contain ':';
    continuation lines begin with four spaces and carry colon-separated hex."""
    sections, order, cur = {}, [], None
    for raw in text.split("\n"):
        if raw == "":
            continue
        if raw.startswith("    "):
            if cur is None:
                raise ValueError("continuation before header: %r" % raw)
            tok = raw.strip()
            if not HEX_LINE.match(tok):
                raise ValueError("non-hex continuation: %r" % raw)
            sections[cur]["cont"].append(tok)
        else:
            key, sep, rest = raw.partition(":")
            if not sep:
                raise ValueError("header without colon: %r" % raw)
            key = key.strip()
            if key in sections:
                raise ValueError("duplicate header: %r" % key)
            sections[key] = {"inline": rest.strip(), "cont": []}
            order.append(key)
            cur = key
    return sections, order


def p1_value(sec):
    inline, cont = sec["inline"], sec["cont"]
    if cont:
        if inline:
            raise ValueError("inline and continuation both present")
        b = bytes.fromhex("".join(cont).replace(":", ""))
        return int.from_bytes(b, "big"), "colon_separated_hex_big_endian", len(b)
    m = re.fullmatch(r"(\d+)(?: \(0x([0-9a-f]+)\))?", inline)
    if not m:
        raise ValueError("unrecognised inline value: %r" % inline)
    v = int(m.group(1))
    if m.group(2) is not None and int(m.group(2), 16) != v:
        raise ValueError("decimal/hex mismatch: %r" % inline)
    return v, ("decimal_with_parenthesised_hex" if m.group(2) else "bare_decimal"), None


def parse_p2(text):
    """Independent regex parser over the whole text."""
    out = {}

    def hexblock(label):
        m = re.search(r"^" + re.escape(label) + r":[ ]*\n((?:[ ]{4}[0-9a-f:]+(?:\n|$))+)", text, re.M)
        if m is None:
            return None
        digits = re.sub(r"[^0-9a-f]", "", m.group(1))
        return int(digits, 16), len(digits) // 2

    def inline(label):
        m = re.search(r"^" + re.escape(label) + r":[ ]+(\d+)(?:[ ]+\(0x([0-9a-f]+)\))?[ ]*$", text, re.M)
        if m is None:
            return None
        return int(m.group(1))

    for label, key in [("Polynomial", "f"), ("A", "A"), ("B", "B"),
                       ("Generator (uncompressed)", "G"), ("Order", "l"), ("Seed", "seed")]:
        hb = hexblock(label)
        if hb is not None:
            out[key], out[key + "_nbytes"] = hb
        else:
            v = inline(label)
            if v is not None:
                out[key] = v
    out["h"] = inline("Cofactor")
    out["header_bits"] = int(re.search(r"^EC-Parameters: \((\d+) bit\)$", text, re.M).group(1))
    out["field_type"] = re.search(r"^Field Type: (.+)$", text, re.M).group(1).strip()
    out["basis_type"] = re.search(r"^Basis Type: (.+)$", text, re.M).group(1).strip()
    return out


# =========================================================== impl-1 arithmetic
class GF2N:
    """F_2[t]/(f); an element is a Python int whose bit j is the coefficient of t^j."""

    def __init__(self, f):
        self.f = f
        self.N = f.bit_length() - 1

    def red(self, x):
        N, f = self.N, self.f
        bl = x.bit_length()
        while bl > N:
            x ^= f << (bl - 1 - N)
            bl = x.bit_length()
        return x

    def mul(self, a, b):
        r = 0
        while b:
            if b & 1:
                r ^= a
            a <<= 1
            b >>= 1
        return self.red(r)

    def sq(self, a):
        return self.mul(a, a)

    def frob(self, a, e):
        """a^(2^e) by e squarings."""
        for _ in range(e):
            a = self.sq(a)
        return a

    def inv(self, a):
        if a == 0:
            raise ZeroDivisionError("inverse of 0")
        u, v, g1, g2 = a, self.f, 1, 0
        while u != 1:
            j = u.bit_length() - v.bit_length()
            if j < 0:
                u, v = v, u
                g1, g2 = g2, g1
                j = -j
            u ^= v << j
            g1 ^= g2 << j
        return self.red(g1)


def pmod(a, b):
    db = b.bit_length()
    while a.bit_length() >= db:
        a ^= b << (a.bit_length() - db)
    return a


def pgcd(a, b):
    while b:
        a, b = b, pmod(a, b)
    return a


def own_prime_factors(n):
    out, p = [], 2
    while p * p <= n:
        if n % p == 0:
            out.append(p)
            while n % p == 0:
                n //= p
        p += 1
    if n > 1:
        out.append(n)
    return out


def rabin_irreducible(F):
    """Rabin: f of degree N is irreducible iff t^(2^N) = t mod f and
    gcd(t^(2^(N/p)) - t, f) = 1 for every prime p | N."""
    N, t = F.N, 2
    if F.frob(t, N) != t:
        return False
    for p in own_prime_factors(N):
        if pgcd(F.frob(t, N // p) ^ t, F.f) != 1:
            return False
    return True


def rank_xor_basis(vectors):
    basis = {}
    for v in vectors:
        while v:
            p = v.bit_length() - 1
            if p in basis:
                v ^= basis[p]
            else:
                basis[p] = v
                break
    return len(basis)


def ec_on_curve(F, A, B, P):
    x, y = P
    x2 = F.sq(x)
    return (F.sq(y) ^ F.mul(x, y)) == (F.mul(x2, x) ^ F.mul(A, x2) ^ B)


def ec_dbl(F, A, P):
    if P is None:
        return None
    x1, y1 = P
    if x1 == 0:
        return None
    lam = x1 ^ F.mul(y1, F.inv(x1))
    x3 = F.sq(lam) ^ lam ^ A
    y3 = F.sq(x1) ^ F.mul(lam, x3) ^ x3
    return (x3, y3)


def ec_add(F, A, P, Q):
    if P is None:
        return Q
    if Q is None:
        return P
    x1, y1 = P
    x2, y2 = Q
    if x1 == x2:
        if (y1 ^ y2) == x1:          # Q = -P, where -(x, y) = (x, x + y)
            return None
        if y1 == y2:
            return ec_dbl(F, A, P)
        raise ValueError("inconsistent points")
    lam = F.mul(y1 ^ y2, F.inv(x1 ^ x2))
    x3 = F.sq(lam) ^ lam ^ x1 ^ x2 ^ A
    y3 = F.mul(lam, x1 ^ x3) ^ x3 ^ y1
    return (x3, y3)


def ec_mul(F, A, k, P):
    R = None
    for bit in bin(k)[2:]:
        R = ec_dbl(F, A, R)
        if bit == "1":
            R = ec_add(F, A, R, P)
    return R


def divisors(N):
    return [d for d in range(1, N + 1) if N % d == 0]


def is_pow2(n):
    return n > 0 and (n & (n - 1)) == 0


# =========================================================== impl-2 machinery
K2 = SymGF(2)
XSYM = symbols("x")


def int_to_gfl(x):
    if x == 0:
        return []
    return [ZZ((x >> j) & 1) for j in range(x.bit_length() - 1, -1, -1)]


def gfl_to_vec(L, N):
    v = np.zeros(N, dtype=np.float64)
    n = len(L)
    for i, c in enumerate(L):
        if int(c) % 2:
            v[n - 1 - i] = 1.0
    return v


def vec_to_int(v):
    out = 0
    for j in np.nonzero(np.asarray(v).astype(np.int64) % 2)[0]:
        out |= 1 << int(j)
    return out


def dm_rank(rows01, ncols):
    dm = DomainMatrix([[K2(int(v)) for v in r] for r in rows01], (len(rows01), ncols), K2)
    return dm.rank()


class Impl2:
    def __init__(self, f):
        self.N = f.bit_length() - 1
        self.F = int_to_gfl(f)
        N = self.N
        M = np.zeros((N, N), dtype=np.float64)
        cur, t2 = [ZZ(1)], [ZZ(1), ZZ(0), ZZ(0)]          # t^0 and t^2
        for j in range(N):                                # column j = t^(2j) mod f
            M[:, j] = gfl_to_vec(cur, N)
            cur = gt.gf_rem(gt.gf_mul(cur, t2, 2, ZZ), self.F, 2, ZZ)
        self.M = M
        self.I = np.eye(N, dtype=np.float64)
        self._pow_cache = {}

    def mpow(self, e):
        if e in self._pow_cache:
            return self._pow_cache[e]
        R, Bm, k = self.I.copy(), self.M.copy(), e
        while k:
            if k & 1:
                R = np.mod(R @ Bm, 2.0)
            Bm = np.mod(Bm @ Bm, 2.0)
            k >>= 1
        self._pow_cache[e] = R
        return R

    def vec(self, x):
        return np.array([(x >> j) & 1 for j in range(self.N)], dtype=np.float64)

    def apply(self, Mat, v):
        return np.mod(Mat @ v, 2.0)

    def in_subfield(self, x, d):
        v = self.vec(x)
        return not np.any(np.mod(self.apply(self.mpow(d), v) - v, 2.0))

    def degree_over_F2(self, x):
        X = int_to_gfl(x)
        rows, p = [], [ZZ(1)]
        for _ in range(self.N):
            rows.append(gfl_to_vec(p, self.N).astype(np.int64).tolist())
            p = gt.gf_rem(gt.gf_mul(p, X, 2, ZZ), self.F, 2, ZZ)
        return dm_rank(rows, self.N)

    def gmul(self, a, b):
        return gt.gf_rem(gt.gf_mul(a, b, 2, ZZ), self.F, 2, ZZ)

    def on_curve(self, A, B, x, y):
        a, b, X, Y = (int_to_gfl(v) for v in (A, B, x, y))
        X2 = self.gmul(X, X)
        lhs = gt.gf_add(self.gmul(Y, Y), self.gmul(X, Y), 2, ZZ)
        rhs = gt.gf_add(gt.gf_add(self.gmul(X2, X), self.gmul(a, X2), 2, ZZ), b, 2, ZZ)
        return gt.gf_strip(lhs) == gt.gf_strip(rhs)


def newton_trace_vector(f, N):
    """Tr_{K/F_2}(t^k) = k-th power sum of the roots of f, by Newton's identities mod 2.
    e_i := coefficient of x^(N-i) in f (signs vanish in characteristic 2)."""
    e = [0] * (N + 1)
    for i in range(1, N + 1):
        e[i] = (f >> (N - i)) & 1
    p = [0] * N
    p[0] = N % 2
    for k in range(1, N):
        s = (k * e[k]) % 2
        for i in range(1, k):
            if e[i]:
                s ^= p[k - i]
        p[k] = s
    return p


def trace_newton(A, tv):
    s, j = 0, 0
    while A >> j:
        if (A >> j) & 1:
            s ^= tv[j]
        j += 1
    return s


_FACTOR_CACHE = {}


def factor_xn_minus_1(n):
    if n not in _FACTOR_CACHE:
        P = Poly(XSYM ** n - 1, XSYM, modulus=2)
        _FACTOR_CACHE[n] = (P, P.factor_list()[1])
    return _FACTOR_CACHE[n]


def annihilator(conj_vecs, n):
    """Least-degree P | x^n - 1 over GF(2) with P(sigma) beta = 0, where
    conj_vecs[i] = sigma^i(beta), i = 0..n-1."""
    P, facs = factor_xn_minus_1(n)

    def applies_to_zero(Q):
        coeffs = Q.all_coeffs()[::-1]   # low -> high
        acc = np.zeros_like(conj_vecs[0])
        for i, c in enumerate(coeffs):
            if int(c) % 2:
                acc = acc + conj_vecs[i]
        return not np.any(np.mod(acc, 2.0))

    for g, mult in facs:
        for _ in range(mult):
            Q, R = P.div(g)
            if not R.is_zero:
                break
            if applies_to_zero(Q):
                P = Q
            else:
                break
    return P


def ann_degree_and_at1(P):
    deg = P.degree()
    at1 = sum(int(c) % 2 for c in P.all_coeffs()) % 2
    return deg, at1


def lucas_recurrence(t, q0, k):
    s = [2, t]
    for i in range(1, k):
        s.append(t * s[i] - q0 * s[i - 1])
    return s[: k + 1]


def lucas_polymod(t, q0, k):
    """s_k = alpha^k + beta^k, from x^k mod (x^2 - t x + q0) = u x + v: s_k = u t + 2 v."""
    def mm(a, b):
        a1, a0 = a
        b1, b0 = b
        c2, c1, c0 = a1 * b1, a1 * b0 + a0 * b1, a0 * b0
        return (c1 + c2 * t, c0 - c2 * q0)
    r, base, e = (0, 1), (1, 0), k
    while e:
        if e & 1:
            r = mm(r, base)
        base = mm(base, base)
        e >>= 1
    u, v = r
    return u * t + 2 * v


SMALL_PRIMES = list(sympy.primerange(2, 200))


def own_miller_rabin(n, rounds, rng):
    if n < 2:
        return False, []
    for p in SMALL_PRIMES:
        if n % p == 0:
            return n == p, []
    d, s = n - 1, 0
    while d % 2 == 0:
        d //= 2
        s += 1
    bases = SMALL_PRIMES + [rng.randrange(2, n - 1) for _ in range(rounds)]
    for a in bases:
        x = pow(a, d, n)
        if x == 1 or x == n - 1:
            continue
        for _ in range(s - 1):
            x = x * x % n
            if x == n - 1:
                break
        else:
            return False, bases
    return True, bases


def machin_pi(prec):
    with localcontext() as ctx:
        ctx.prec = prec + 15

        def arctan_inv(xi):
            x = Decimal(xi)
            x2 = x * x
            term = Decimal(1) / x
            total = term
            k = 0
            eps = Decimal(10) ** (-(prec + 12))
            while True:
                k += 1
                term /= x2
                delta = term / (2 * k + 1)
                if delta < eps:
                    break
                total = total - delta if k % 2 else total + delta
            return total

        pi = 4 * (4 * arctan_inv(5) - arctan_inv(239))
    with localcontext() as ctx:
        ctx.prec = prec
        return +pi


def fmt4(intval):
    a = abs(intval)
    return ("-" if intval < 0 else "") + "%d.%04d" % (a // 10000, a % 10000)


def round_fraction_4dp(fr):
    scaled = fr * 10000
    fl = scaled.numerator // scaled.denominator
    rem = scaled - fl
    half = Fraction(1, 2)
    if rem > half:
        return fmt4(fl + 1), fmt4(fl + 1), False
    if rem < half:
        return fmt4(fl), fmt4(fl), False
    return fmt4(fl if fl % 2 == 0 else fl + 1), fmt4(fl + 1), True


def exact_decimal_or_fraction(fr):
    """Terminating decimal expansion if the denominator is 2^a 5^b, else 'p/q'."""
    d = fr.denominator
    while d % 2 == 0:
        d //= 2
    while d % 5 == 0:
        d //= 5
    if d != 1:
        return "%d/%d" % (fr.numerator, fr.denominator)
    with localcontext() as ctx:
        ctx.prec = 200
        return str(Decimal(fr.numerator) / Decimal(fr.denominator))


def hx(v):
    return "0x" + format(v, "x")


# =========================================================== main computation
mpmath.mp.dps = 60
MACHIN_PI = machin_pi(70)

results = {"rows": {}, "controls": [], "sensitivity": {}, "agreement_failures": []}


def agree(label, v1, v2):
    if v1 != v2:
        results["agreement_failures"].append({"check": label, "impl1": repr(v1), "impl2": repr(v2)})
    return v1 == v2


for row in ROWS:
    t_row = time.perf_counter()
    text = open(os.path.join(RAW_DIR, row + ".stdout")).read()
    R = {"row": row, "group": "composite" if row in ROWS_COMPOSITE else "prime_degree_control"}

    # ---------------- parse (two independent parsers must agree)
    t0 = time.perf_counter()
    secs, order = parse_p1(text)
    p1 = {}
    for key, name in [("Polynomial", "f"), ("A", "A"), ("B", "B"), ("Generator (uncompressed)", "G"),
                      ("Order", "l"), ("Cofactor", "h")]:
        p1[name], p1[name + "_form"], p1[name + "_nbytes"] = p1_value(secs[key])
    p1["seed"] = p1_value(secs["Seed"])[0] if "Seed" in secs else None
    p1["header_bits"] = int(re.fullmatch(r"\((\d+) bit\)", secs["EC-Parameters"]["inline"]).group(1))
    p1["field_type"] = secs["Field Type"]["inline"]
    p1["basis_type"] = secs["Basis Type"]["inline"]
    p2 = parse_p2(text)
    parse_agree = all(p1[k] == p2.get(k) for k in ["f", "A", "B", "G", "l", "h", "seed", "header_bits",
                                                   "field_type", "basis_type"]
                      if not (k == "seed" and p1["seed"] is None and "seed" not in p2))
    agree(row + ":parsers_P1_P2", True, parse_agree)
    f, A, B, l, h = p1["f"], p1["A"], p1["B"], p1["l"], p1["h"]
    N = f.bit_length() - 1
    Gb = p1["G"].to_bytes(p1["G_nbytes"], "big")
    L = (len(Gb) - 1) // 2
    assert Gb[0] == 4 and len(Gb) == 1 + 2 * L
    Gx, Gy = int.from_bytes(Gb[1:1 + L], "big"), int.from_bytes(Gb[1 + L:], "big")
    R["parse"] = {
        "section_order": order, "field_type": p1["field_type"], "basis_type": p1["basis_type"],
        "header_bits": p1["header_bits"], "f": f, "A": A, "B": B, "Gx": Gx, "Gy": Gy, "l": l, "h": h,
        "seed": p1["seed"], "forms": {k: p1[k + "_form"] for k in ["f", "A", "B", "G", "l", "h"]},
        "G_coordinate_bytes": L, "parsers_agree": parse_agree,
    }
    tick("parse", t0)

    F = GF2N(f)
    I2 = Impl2(f)

    # ---------------- self-checks of the parsed parameters
    t0 = time.perf_counter()
    irr1 = rabin_irreducible(F)
    irr2 = bool(gt.gf_irreducible_p(I2.F, 2, ZZ))
    agree(row + ":f_irreducible", irr1, irr2)
    inv_ok = all(F.mul(z, F.inv(z)) == 1 for z in [A or 1, B, Gx, Gy])
    oc1 = ec_on_curve(F, A, B, (Gx, Gy))
    oc2 = I2.on_curve(A, B, Gx, Gy)
    agree(row + ":G_on_curve", oc1, oc2)
    lG = ec_mul(F, A, l, (Gx, Gy))
    hl = h * l
    hasse_dev = (1 << N) + 1 - hl
    R["self_checks"] = {
        "N_equals_8_times_G_coordinate_bytes_or_less": N <= 8 * L < N + 8,
        "f_irreducible_rabin_impl1": irr1, "f_irreducible_sympy_gf_irreducible_p_impl2": irr2,
        "inverse_roundtrip_impl1": inv_ok,
        "A_B_Gx_Gy_reduced_below_degree_N": all(v.bit_length() <= N for v in [A, B, Gx, Gy]),
        "G_satisfies_curve_equation_impl1": oc1, "G_satisfies_curve_equation_impl2": oc2,
        "l_times_G_is_point_at_infinity_impl1": lG is None,
        "header_bits_equals_l_bit_length": p1["header_bits"] == l.bit_length(),
        "B_nonzero": B != 0,
        "hasse_abs_2N_plus_1_minus_hl": abs(hasse_dev),
        "hasse_bound_holds_(2N+1-hl)^2_le_4*2^N": hasse_dev * hasse_dev <= 4 * (1 << N),
    }
    tick("self_checks", t0)

    # ---------------- Q1
    t0 = time.perf_counter()
    divs = divisors(N)
    exps = [j for j in range(N, -1, -1) if (f >> j) & 1]
    in_sub1 = {d: (F.frob(A, d) == A, F.frob(B, d) == B) for d in divs}
    d_min = min(d for d in divs if in_sub1[d][0] and in_sub1[d][1])
    d_B = min(d for d in divs if in_sub1[d][1])
    d_A = min(d for d in divs if in_sub1[d][0])
    prime_bpsw = bool(sympy.isprime(l))
    mr_ok, mr_bases = own_miller_rabin(l, 64, random.Random(SEED ^ l.bit_length()))
    Q1 = {
