                "subfield_membership_impl1": {str(d): {"A": a_in, "B": b_in} for d, (a_in, b_in) in in_sub1.items()}}
    tick("Q1_impl1", t0)

    # impl-2 for Q1
    t0 = time.perf_counter()
    degA2 = I2.degree_over_F2(A)
    degB2 = I2.degree_over_F2(B)
    in_sub2 = {d: (I2.in_subfield(A, d), I2.in_subfield(B, d)) for d in divs}
    d_min2_matrix = min(d for d in divs if in_sub2[d][0] and in_sub2[d][1])
    d_min2_degree = degA2 * degB2 // math.gcd(degA2, degB2)
    agree(row + ":d_min_matrix", d_min, d_min2_matrix)
    agree(row + ":d_min_power_rank", d_min, d_min2_degree)
    agree(row + ":d_B_power_rank", d_B, degB2)
    agree(row + ":d_A_power_rank", d_A, degA2)
    agree(row + ":primality", prime_bpsw, mr_ok)
    impl2_q1 = {"degree_A_over_F2_power_rank": degA2, "degree_B_over_F2_power_rank": degB2,
                "d_min_matrix": d_min2_matrix, "d_min_lcm_of_degrees": d_min2_degree,
                "miller_rabin_outcome": mr_ok}
    if d_min < N:
