        Q2.append({"c": c, "n": n, "orbit_length": orbit, "m": m, "m_level": m_level,
                   "Tr_A": trA, "condition": cond,
                   "two_pow_m_minus_1": 1 << (m - 1), "two_pow_m_minus_1_minus_1": (1 << (m - 1)) - 1})
        # sensitivity: alternative readings of the span (not card quantities)
        conj_plain, cur = [], B
        for i in range(n):
            conj_plain.append(cur)
            cur = F.frob(cur, c)
        sens_rows.append({
            "c": c, "n": n, "m": m,
            "m_if_square_roots_omitted": rank_xor_basis([(1 << N) | v for v in conj_plain]),
            "m_if_leading_1_omitted_dim_span_sqrt_conjugates": rank_xor_basis(conj_sqrt),
            "orbit_length_of_B_alone": orbitB, "orbit_length_of_A_and_B": orbit,
        })
    R["Q2"] = Q2
    R["sensitivity_span"] = sens_rows
    tick("Q2_impl1", t0)

    # impl-2 for Q2
    t0 = time.perf_counter()
    tv = newton_trace_vector(f, N)
    trA2 = trace_newton(A, tv)
