    vB = I2.vec(B)
    vsqrtB = I2.apply(I2.mpow(N - 1), vB)
    assert not np.any(np.mod(I2.apply(I2.M, vsqrtB) - vB, 2.0))
    agree(row + ":sqrtB", sqrtB, vec_to_int(vsqrtB))
    vA = I2.vec(A)
    for q in Q2:
        c, n = q["c"], q["n"]
        Mc = I2.mpow(c)
        conj2, cur = [], vsqrtB
        for i in range(n):
            conj2.append(cur)
            cur = I2.apply(Mc, cur)
        rows01 = [[1] + v.astype(np.int64).tolist() for v in conj2]
        m2 = dm_rank(rows01, N + 1)
        P = annihilator(conj2, n)
        degP, at1 = ann_degree_and_at1(P)
        m3 = degP + (0 if at1 == 0 else 1)
        conjB, cur = [], vB
        for i in range(n):
            conjB.append(cur)
            cur = I2.apply(Mc, cur)
        PB = annihilator(conjB, n)
        degPB, _ = ann_degree_and_at1(PB)
        if is_pow2(n):
            v, ml2 = vB, None
            for j in range(1, n + 1):
                v = np.mod(I2.apply(Mc, v) + v, 2.0)
                if not np.any(v):
                    ml2 = j
                    break
            ml3 = degPB
        else:
            ml2 = ml3 = "not defined"
        # orbit length: formula and direct matrix iteration
        orbit_formula = d_min2_degree // math.gcd(d_min2_degree, c)
        a, b, orbit2 = vA, vB, None
        for i in range(1, n + 1):
            a, b = I2.apply(Mc, a), I2.apply(Mc, b)
            if not np.any(np.mod(a - vA, 2.0)) and not np.any(np.mod(b - vB, 2.0)):
