        cond2 = (n % 2 == 1) or (m2 == n) or (trA2 == 0)
        agree("%s:c=%d:m_rank_DomainMatrix" % (row, c), q["m"], m2)
        agree("%s:c=%d:m_annihilator" % (row, c), q["m"], m3)
        agree("%s:c=%d:Ord(sqrtB)=Ord(B)_degree" % (row, c), degP, degPB)
        agree("%s:c=%d:m_level_matrix" % (row, c), q["m_level"], ml2)
        agree("%s:c=%d:m_level_annihilator" % (row, c), q["m_level"], ml3)
        agree("%s:c=%d:orbit_formula" % (row, c), q["orbit_length"], orbit_formula)
        agree("%s:c=%d:orbit_matrix" % (row, c), q["orbit_length"], orbit2)
        agree("%s:c=%d:condition" % (row, c), q["condition"], cond2)
        R["impl2"]["Q2"].append({"c": c, "n": n, "m_DomainMatrix_rank": m2, "m_annihilator": m3,
                                 "annihilator_sqrtB_poly_coeffs_high_to_low": [int(x) % 2 for x in P.all_coeffs()],
                                 "deg_Ord_sqrtB": degP, "deg_Ord_B": degPB,
                                 "m_level_matrix": ml2, "m_level_annihilator": ml3,
                                 "orbit_formula": orbit_formula, "orbit_matrix": orbit2,
                                 "Tr_A_newton": trA2, "condition": cond2})
