        else:
            k, k_source = 1, "d_min = N; Q1 defines no k; the same formula N / d_min = 1 used (see Q0)"
        v1 = mpmath.log(mpmath.sqrt(mpmath.pi * mpmath.mpf(l) / (4 * k)), 2)
        with localcontext() as ctx:
            ctx.prec = 60
