        v3 = 0.5 * (math.log2(math.pi) + math.log2(l) - math.log2(4 * k))
        d1 = Decimal(mpmath.nstr(v1, 50, strip_zeros=False))
        r_he = d1.quantize(Decimal("0.0001"), rounding=ROUND_HALF_EVEN)
        r_hu = d1.quantize(Decimal("0.0001"), rounding=ROUND_HALF_UP)
        r2 = v2.quantize(Decimal("0.0001"), rounding=ROUND_HALF_EVEN)
        frac = (d1 * 10000) % 1
        R["Q3"] = {"k": k, "k_source": k_source, "value_4dp": str(r_he),
                   "value_50_significant_digits_mpmath": mpmath.nstr(v1, 50),
                   "value_decimal_machin": str(+v2), "value_float": repr(v3),
                   "distance_of_scaled_fraction_from_rounding_boundary": str(abs(frac - Decimal("0.5"))),
                   "half_even_equals_half_up": r_he == r_hu}
        agree(row + ":Q3_mpmath_vs_decimal", str(r_he), str(r2))
        agree(row + ":Q3_float_4dp", str(r_he), "%.4f" % v3)
        tick("Q3", t0)

        # ---------------- Q4
        t0 = time.perf_counter()
        Q4 = []
