                "R-1": (2 - mpmath.mpf(2) / g) * c,
                "R-2": (1 - mpmath.mpf(1) / g) * c,
                "R-3": mpmath.log(g, 2) + 2 * (1 - mpmath.mpf(1) / g) * c,
                "R-4": mpmath.mpf(g) / c,
