            for key in ["R-1", "R-2", "R-3", "R-4"]:
                he, hu, tie = round_fraction_4dp(fr[key])
                mp_he = Decimal(mpmath.nstr(mpv[key], 40, strip_zeros=False)).quantize(
                    Decimal("0.0001"), rounding=ROUND_HALF_EVEN)
                agree("%s:c=%d:%s_fraction_vs_mpmath" % (row, c, key), he, str(mp_he))
