            cur = I2.apply(Mc, cur)
        P = annihilator(c2, n)
        dP, a1 = ann_degree_and_at1(P)
        m_ann = dP + (0 if a1 == 0 else 1)
        results["controls"].append({"row_field": row, "c": c, "n": n, "control": "NULL-random-b",
                                    "expected_m": "none (agreement only)", "impl1_m": m_i1,
                                    "impl2_m_annihilator": m_ann, "pass": m_i1 == m_ann})
        # trace null object: random field element, conjugate sum vs Newton
